sys_script_include.script:
var AppointmentUtils = Class.create();
AppointmentUtils.prototype = {
    initialize: function() {
    },

    getAllAppointmentForPatient: function(id){
        var app = new GlideRecord('u_appointment');
        app.addQuery('u_patient_id', id);
        app.query();
        return app;
    },

    getConfirmedAppointment: function(id){
        var app = new GlideRecord('u_appointment')
        app.addQuery('number', id)
        app.query();
        if( app.next() && app.u_statis == 'confirmed')
		{
			return "true";
		}
		else{
			return 'false';
		}
    },

    getAppointmentDetailsByID: function(id){
        var app = new GlideRecord('u_appointment')
        if(app.get(id)){
            return app
        }
        else{
            return null
        }
    },

    getAppointmentDetailsByDate: function(date){
        var app = new GlideRecord('u_appointment')
        app.addQuery('u_appointment_date', 'CONTAINS', date);
        app.query();
        if(app.next()){
            return app
        }
        return null
    },

    getAppointmentDetailsByDepartment: function(dep){
        var app = new GlideRecord('u_appointment')
        app.addQuery('u_department', dep)
        app.query()
        return app
    },


    type: 'AppointmentUtils'
};
